class Counter:
    def __init__(self, value=0):
        self.value = value

    def increment(self):
        self.value += 1

count = Counter()
count.increment()
print(count.value)

import math

def circle_area(radius):
    return math.pi * radius ** 2

if __name__ == "__main__":
    print(round(circle_area(2), 2))

def average(values):
    if not values:
        raise ValueError("values must not be empty")
    return sum(values) / len(values)

print(average([4, 6, 8]))
